// Try NewsAPI first, fallback to RSS parsing
const newsApiData = $('Fetch News (NewsAPI)').first().json;
const rssData = $('NYT RSS Fallback').first().json;

let articles = [];

// Parse NewsAPI response
if (newsApiData.articles && newsApiData.articles.length > 0) {
  articles = newsApiData.articles.slice(0, 10).map(a => ({
    title: a.title,
    description: a.description,
    source: a.source?.name || 'Unknown',
    url: a.url,
    publishedAt: a.publishedAt
  }));
} else {
  // Fallback: parse RSS XML as text
  const rssText = typeof rssData === 'string' ? rssData : JSON.stringify(rssData);
  // Basic RSS title extraction
  const titleMatches = rssText.match(/<title>([^<]+)<\/title>/g) || [];
  articles = titleMatches.slice(1, 11).map((m, i) => ({
    title: m.replace(/<\/?title>/g, ''),
    description: '',
    source: 'NYT RSS',
    url: '',
    publishedAt: new Date().toISOString()
  }));
}

const now = new Date();
const dateStr = now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

return {
  json: {
    date: dateStr,
    articleCount: articles.length,
    articles: articles,
    summary: articles.slice(0, 5).map((a, i) => `${i+1}. ${a.title} (${a.source})`).join('\n'),
    categories: [...new Set(articles.map(a => a.source))]
  }
};
